import{_ as t,o,c as n,ah as r}from"./chunks/framework.C5RNlfrV.js";const a="data:image/png;base64,",i="data:image/png;base64,",u=JSON.parse('{"title":"9. Read First！！！","description":"","frontmatter":{},"headers":[],"relativePath":"docs/9.Read First！！！.md","filePath":"docs/9.Read First！！！.md"}'),s={name:"docs/9.Read First！！！.md"};function c(A,e,l,d,h,p){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_9-read-first" tabindex="-1">9. Read First！！！ <a class="header-anchor" href="#_9-read-first" aria-label="Permalink to &quot;9. Read First！！！&quot;">​</a></h1><h2 id="_9-1-remote-control" tabindex="-1">9.1 Remote Control <a class="header-anchor" href="#_9-1-remote-control" aria-label="Permalink to &quot;9.1 Remote Control&quot;">​</a></h2><p>There are two ways to remotely control the robot: graphical and command-line control.</p><p>VNC is a graphical remote control software. After installation, you can directly control the robot on your computer by connecting to the robot&#39;s hotspot. If the VNC is used for the Raspberry Pi 5 controller, the robot&#39;s system desktop can be clearly seen. This is convenient for intuitive operation.</p><p>Compared to VNC, MobaXterm is an SSH connection that focuses more on command-line control. It does not display the complete desktop of the robot&#39;s system, only the command-line window. If you are proficient in command-line operations, you can use commands to control the robot more quickly while reducing computational and memory usage. MobaXterm has a built-in lightweight X11 server that can directly display the interface of graphical applications.</p><p>The tutorial for this robot uses MobaXterm connection as an example for demonstration, and it is also applicable for VNC.</p><p>For terminal usage, when using MobaXterm to connect, you need to enter commands to enter the Docker environment.</p><p>When using VNC to connect, there are two terminals to choose from. <img loading="lazy" height="37" width="40" src="'+a+'" class="inline-icon"> accesses directly to the container. <img loading="lazy" height="31" width="39" src="'+i+'" class="inline-icon">requires you to enter commands to enter the Docker environment.</p><p>Enter “docker exec -it -u ubuntu -w /home/ubuntu 82df /bin/bash” can enter the container. Enter “exit” can exit the container.</p><p>Stopping the ROS service needs to run the “~/.stop_ros.sh” script under Docker. Starting it needs to exit the Docker environment and enable the auto-start service with “sudo systemctl restart start_node.service”.</p>',10)])])}const g=t(s,[["render",c]]);export{u as __pageData,g as default};
